package org.xwiki.scratch.scratch;

import java.util.List;
import java.util.regex.Pattern;

import jakarta.inject.Inject;
import jakarta.inject.Named;
import jakarta.inject.Provider;
import jakarta.inject.Singleton;

import org.slf4j.Logger;

import org.xwiki.component.annotation.Component;
import org.xwiki.model.reference.DocumentReference;
import org.xwiki.script.service.ScriptService;

import com.xpn.xwiki.XWiki;
import com.xpn.xwiki.XWikiContext;
import com.xpn.xwiki.doc.XWikiDocument;
import com.xpn.xwiki.XWikiException;
import java.net.URI;
import java.net.URISyntaxException;

@Component
@Singleton
@Named("allowedurls")
public class AllowedURLsScriptService implements ScriptService
{
    private Pattern prefixPattern; 

    @Inject
    private Logger logger;

    @Inject
    private Provider<XWikiContext> contextProvider;

    public void refresh()
    {
        // We build a mega regex containing all the allowed prefixes.
        XWikiContext context = contextProvider.get();
        XWiki wiki = context.getWiki();

        try {
            DocumentReference ref =
                new DocumentReference(context.getWikiId(), List.of("AllowedURLs", "Code"), "AllowedURLs");
            StringBuilder prefixPatternBuilder = new StringBuilder();
            XWikiDocument allowedURLsDoc = wiki.getDocument(ref, context);
            if (!allowedURLsDoc.isNew()) {
                for (String prefixUntrimmed : allowedURLsDoc.getContent().split("\n")) {
                    String prefix = prefixUntrimmed.trim();
                    if (!prefix.isEmpty() && prefix.charAt(0) != '#') {
                        try {
                            if (!prefix.startsWith("//") && !new URI(prefix).isAbsolute()) {
                                if (!prefix.endsWith("/")) {
                                    prefix = prefix + "/";
                                }
                                addPrefix(prefixPatternBuilder, "http://" + prefix);
                                addPrefix(prefixPatternBuilder, "https://" + prefix);
                            } else {
                                addPrefix(prefixPatternBuilder, prefix);
                            }
                        } catch (URISyntaxException e) {
                            addPrefix(prefixPatternBuilder, prefix);
                        }
                    }
                }
            }
            prefixPattern = Pattern.compile(prefixPatternBuilder.toString());
        } catch (XWikiException e) {
            logger.error("Failed to refresh the allowed URLs", e);
        }
    }

    private void addPrefix(StringBuilder prefixPatternBuilder, String prefix)
    {
        if (!prefixPatternBuilder.isEmpty()) {
            prefixPatternBuilder.append("|");
        }
        prefixPatternBuilder.append("^");
        prefixPatternBuilder.append(Pattern.quote(prefix));
        prefixPatternBuilder.append("[\\s\\S]*");
    }

    public boolean isAllowed(String url)
    {
        if (prefixPattern == null) {
            refresh();
        }

        if (prefixPattern == null) {
            return false;
        }

        return prefixPattern.matcher(url).matches();
    }
}
